// PolyLab Web App Entry Point

async function main() {
    const statusEl = document.getElementById('status')!;

    try {
        statusEl.textContent = 'Loading WebAssembly module...';

        // Import the WASM module (generated by wasm-pack)
        const wasmModule = await import('../../../crates/polylab-viewer/pkg/polylab_viewer.js');
        await wasmModule.default();

        statusEl.textContent = 'Creating viewer...';

        // Create viewer instance (using create() instead of new constructor)
        const viewer = await wasmModule.ViewerHandle.create('webgpu-canvas');

        statusEl.textContent = '✅ Rendering!';

        // Animation loop
        function animate() {
            try {
                viewer.render();
                requestAnimationFrame(animate);
            } catch (e) {
                console.error('Render error:', e);
                statusEl.textContent = `❌ Error: ${e}`;
            }
        }

        animate();

    } catch (error) {
        console.error('Failed to initialize:', error);
        statusEl.textContent = `❌ Error: ${error}`;

        // Check if WebGPU is supported
        if (!navigator.gpu) {
            statusEl.textContent = '❌ WebGPU is not supported in this browser. Try Chrome/Edge 113+ or Firefox Nightly.';
        }
    }
}

// Check WebGPU support before starting
if (!navigator.gpu) {
    document.getElementById('status')!.textContent =
        '❌ WebGPU is not supported. Please use Chrome 113+, Edge 113+, or Firefox Nightly with WebGPU enabled.';
} else {
    main();
}
